# %% [markdown]
# ## Step 2 — The Problem: Agent Evaluation
#
# An eval harness solves three failure modes in agent benchmarking:
#
# 1. **Unverified pass**: Agent claims success but didn't actually fix anything
# 2. **Undetected regression**: Change makes one task worse, hidden in aggregate scores
# 3. **Per-task drift**: Test suite changes silently (renamed fixtures, missing tasks)
#
# The solution: a deterministic verifier that checks each run against known-good output.

# %%
# Let's define the core data structures for an eval harness
from dataclasses import dataclass
from typing import Any
import tempfile, shutil, os, time, statistics

@dataclass
class FixtureTask:
    """A single evaluation task: goal + setup files + verifier."""
    id: str
    goal: str
    setup_files: dict[str, str]  # filename -> content
    expected_files: dict[str, str]  # filename -> expected content
    verifier_name: str
    verifier_args: dict[str, Any]

@dataclass
class SampleResult:
    """One execution of a candidate against a task."""
    task_id: str
    sample_index: int
    latency_ms: float
    cost_units: float = 0.0
    notes: str = ""

print("✅ Data structures defined")

# %% [markdown]
# ## Step 3 — Deterministic Verifiers
#
# A verifier is a function that checks if the agent's output matches expected behavior. We'll implement `file_equals`: compare a file in the agent's output against a known-good file.

# %%
def verify_file_equals(scratch_files: dict[str, str], expected_files: dict[str, str], args: dict) -> tuple[bool, str]:
    """Compare a file from agent output against expected."""
    path = args.get("path")
    if path not in scratch_files:
        return False, f"Output file missing: {path}"
    if path not in expected_files:
        return False, f"Expected file missing: {path}"
    actual = scratch_files[path].rstrip("\n") + "\n"
    expected = expected_files[path].rstrip("\n") + "\n"
    if actual == expected:
        return True, f"File '{path}' matches expected"
    return False, f"File '{path}' differs from expected"

print("✅ file_equals verifier defined")

