# %% [markdown]
# ## Step 6 — Verify the Agent's Output
#
# Extract the code from the agent's response and check it against the expected file:

# %%
import re

# Extract code from markdown blocks if present
def extract_code(text: str) -> str:
    # Remove markdown code blocks
    match = re.search(r'```(?:python)?\s*\n(.+?)\n```', text, re.DOTALL)
    if match:
        return match.group(1)
    return text.strip()

agent_code = extract_code(agent_output)

# Create scratch_files dict (what the agent produced)
scratch_files = {"fizzbuzz.py": agent_code}

# Run the verifier
passed, detail = verify_file_equals(scratch_files, fizzbuzz_task.expected_files, fizzbuzz_task.verifier_args)

print(f"Verification result: {detail}")
print(f"Sample passed: {passed}")

# %% [markdown]
# ## Step 7 — pass@k: Multiple Samples
#
# Real LLM agents are stochastic. We measure pass@k: the probability of at least one correct answer in k independent samples. The formula is: **pass@k = 1 - (1 - p)^k** where p is the empirical pass rate.

# %%
def pass_at_k(empirical_pass_rate: float, k: int) -> float:
    """Probability of at least one pass in k independent samples."""
    if k <= 0:
        return 0.0
    p = max(0.0, min(1.0, empirical_pass_rate))
    return 1.0 - (1.0 - p) ** k

# Example: if agent passes 60% of tries, what's the chance of success in k samples?
for k_val in [1, 3, 5, 10]:
    prob = pass_at_k(0.6, k_val)
    print(f"pass@{k_val}: {prob:.4f}  (with p=0.6)")

# %% [markdown]
# ## Step 8 — Run Multiple Samples
#
# Let's ask Claude multiple times and compute pass@k:

# %%
# Run 3 samples
k = 3
passes = 0
results = []

for sample_idx in range(k):
    prompt = f"""Here is a buggy Python function:

{buggy_fizzbuzz}

Goal: {fizzbuzz_task.goal}

Respond with ONLY the corrected Python code, no explanation."""
    
    r = await lrn_llm.call(
        [{"role": "user", "content": prompt}],
        max_tokens=300
    )
    
    agent_code = extract_code(lrn_llm.text(r))
    scratch_files = {"fizzbuzz.py": agent_code}
    passed, detail = verify_file_equals(scratch_files, fizzbuzz_task.expected_files, fizzbuzz_task.verifier_args)
    
    if passed:
        passes += 1
    
    results.append({"sample": sample_idx, "passed": passed, "detail": detail})
    print(f"Sample {sample_idx}: {'✅ PASS' if passed else '❌ FAIL'} - {detail}")

pass_rate = passes / k
pass_at_k_value = pass_at_k(pass_rate, k)

print(f"\nSummary:")
print(f"  Passes: {passes}/{k}")
print(f"  Pass@1: {pass_rate:.4f}")
print(f"  Pass@{k}: {pass_at_k_value:.4f}")

# %% [markdown]
# ## Step 9 — Aggregate Metrics
#
# The harness computes:
# - **pass@1**: Probability of success on first try
# - **pass@k**: Probability of success in k tries  
# - **mean_latency_ms**: Average time per sample
# - **p95_latency_ms**: 95th percentile latency
# - **mean_cost**: Average LLM cost per sample

# %%
def percentile_95(values: list[float]) -> float:
    """95th percentile via nearest-rank."""
    if not values:
        return 0.0
    sorted_vals = sorted(values)
    idx = max(0, int(round(0.95 * len(sorted_vals))) - 1)
    return sorted_vals[min(idx, len(sorted_vals) - 1)]

# Example latencies (in ms) from our runs
latencies = [120.5, 115.3, 118.7]
costs = [1.2, 1.2, 1.2]  # Arbitrary cost units

mean_latency = statistics.mean(latencies)
p95_latency = percentile_95(latencies)
mean_cost = statistics.mean(costs)

print(f"Task Report:")
print(f"  Task ID: {fizzbuzz_task.id}")
print(f"  k: {k}")
print(f"  Passes: {passes}/{k}")
print(f"  Pass@1: {pass_rate:.4f}")
print(f"  Pass@k: {pass_at_k_value:.4f}")
print(f"  Mean latency: {mean_latency:.1f} ms")
print(f"  P95 latency: {p95_latency:.1f} ms")
print(f"  Mean cost: {mean_cost:.4f} units")

# %% [markdown]
# ## Step 10 — Structured Report (JSON)
#
# The harness emits a structured JSON report that regression-tracking scripts can ingest:

# %%
report = {
    "task_id": fizzbuzz_task.id,
    "k": k,
    "passes": passes,
    "pass_rate": round(pass_rate, 4),
    "pass_at_k": round(pass_at_k_value, 4),
    "mean_latency_ms": round(mean_latency, 3),
    "p95_latency_ms": round(p95_latency, 3),
    "mean_cost": round(mean_cost, 4),
    "samples": results
}

print(json.dumps(report, indent=2))

